STAT = {}


def _rec(label, dt, **extra):
    s = STAT.setdefault(label, {"calls": 0, "seconds": 0.0})
    s["calls"] += 1
    s["seconds"] += dt
    for k, v in extra.items():
        s[k] = s.get(k, 0) + v


class Instr:
    """Counting and timing wrappers on named attributes; off() puts every original back."""

    def __init__(self):
        self.saved = []

    def wrap(self, obj, name, label, extra=None):
        orig = getattr(obj, name)

        def timed(*a, **k):
            t0 = time.perf_counter()
            r = orig(*a, **k)
            dt = time.perf_counter() - t0
            _rec(label, dt, **(extra(a, k, r) if extra else {}))
            return r
        self.saved.append((obj, name, orig, name in getattr(obj, "__dict__", {})))
        setattr(obj, name, timed)

    def off(self):
        for obj, name, orig, had in reversed(self.saved):
            if had:
                setattr(obj, name, orig)
            else:
                delattr(obj, name)
        self.saved = []


def instrument(ins, chk, R):
    ctx = R.ctx
    for n in ("home_clearance", "beaker_on_hotplate_clearance", "neck_spread", "occlusion", "framing_slack", "place"):
        ins.wrap(chk, n, f"check.{n}")
    ins.wrap(SC, "frame_points", "neck.frame_points (one neck framing solve)")
    ins.wrap(SC, "best_margin", "neck.best_margin (the framing slack search)")
    ins.wrap(NF, "_evaluate", "neck._evaluate (one cost evaluation of the framing search)")
    ins.wrap(NF._Scratch, "__init__", "neck._Scratch.__init__ (a framing workspace: a new MjData each time)")
    ins.wrap(NF._Scratch, "pose", "neck._Scratch.pose (best_margin's forward kinematics)")
    ins.wrap(NF._Scratch, "contacts", "neck._Scratch.contacts (neck collision check)")
    ins.wrap(mujoco, "mj_geomDistance", "mujoco.mj_geomDistance (one geom pair distance)")
    ins.wrap(mujoco.Renderer, "render", "render (one segmentation render)")
    ins.wrap(mujoco.Renderer, "update_scene", "render.update_scene")
    ins.wrap(SC.OcclusionMeter, "_count", "occlusion._count (one render + its pixel counting)")
    ins.wrap(R, "evaluate", "ik.R.evaluate (the IK verification)")
    ins.wrap(R, "plain", "ik.R.plain (one IK support test of 1 to 8 stances)", lambda a, k, r: {"stances": len(np.atleast_2d(a[0]))})
    ins.wrap(R, "analyze", "ik.R.analyze (nominal support with collisions and furniture)")
    ins.wrap(ctx, "supports", "ik.ctx.supports")
    ins.wrap(ctx, "solve", "ik.ctx.solve (all 12 bins of a set of targets)")
    ins.wrap(AC.ArmCollisionChecker, "__init__", "ik.ArmCollisionChecker.__init__ (copies the model)")

    def ik_extra(a, k, r):
        Q0 = a[1]
        iters = np.asarray(r[2])
        return {"starts": int(len(Q0)), "iterations_total": int(iters.sum()), "solved": int(np.asarray(r[1]).sum())}
    ins.wrap(S2, "solve_ik", "ik.solve_ik (one batch of damped least squares starts)", ik_extra)
    ins.wrap(SS, "solve_ik", "ik.solve_ik (warm path, not used here)", ik_extra)


def layer3(chk, R, x, y, q_lo, q_hi, heading, qs):
    """One layer 3 check, as in experiments/stance_selection_timing.py; returns a dict of times and results."""
    t0 = time.perf_counter()
    heights = [float(q) for q in qs if q_lo - 1e-9 <= q <= q_hi + 1e-9]
    rows = [SFM.req_row(chk, (x, y, heading, q)) for q in heights]
    t_req = time.perf_counter() - t0
    passing = [i for i, r in enumerate(rows) if r["ok"]]
    t1 = time.perf_counter()
    ev = None
    q_mid = None
    if passing:
        q_mid = heights[passing[len(passing) // 2]]
        ev = R.evaluate(np.array([x, y, heading, q_mid]))
    t_ik = time.perf_counter() - t1
    return {"heights": len(heights), "passing_heights": len(passing), "failed_at": sorted({f for r in rows for f in r["failed"]}), "q_mid": q_mid,
            "requirements_seconds": round(t_req, 2), "ik_seconds": round(t_ik, 2), "total_seconds": round(t_req + t_ik, 2), "ik_points_ok": None if ev is None else int(ev["points_ok_self"]),
            "points": None if ev is None else int(ev["points"])}


def snapshot():
    out = {k: {kk: (round(vv, 3) if isinstance(vv, float) else vv) for kk, vv in v.items()} for k, v in STAT.items()}
    STAT.clear()
    return out


def main(args):
    t_setup = time.perf_counter()
    maps_free = None                                         # layer 2 is not part of layer 3: no reach maps are loaded
    R = SS.Runner("open_b45", {**SFM.CASES["open_b45"], "cameras": True})
    t_runner = time.perf_counter() - t_setup
    ctx = R.ctx
    m = ctx.m
    m.body_pos[m.body("task_hotplate").id] = [ctx.hotplate_xy[0], ctx.hotplate_xy[1], ctx.top]
    data = ctx.data
    apply_task_poses(m, data, {**TASK_CFG, "beaker_xy": tuple(ctx.beaker_xy), "hotplate_xy": tuple(ctx.hotplate_xy)})
    mujoco.mj_forward(m, data)
    t1 = time.perf_counter()
    chk = StanceChecks(m, data, ctx.rg["base_z"])
    t_chk = time.perf_counter() - t1
    qs = np.round(np.arange(0.0, 0.3001, 0.01), 4)
    heading = math.radians(-90.0)
    out = {"setup_seconds": {"Runner (load_task, S2.Ctx, furniture and body checks, IK chain)": round(t_runner, 2), "StanceChecks": round(t_chk, 2)}}
    print(f"setup: Runner {t_runner:.1f} s, StanceChecks {t_chk:.1f} s")
    A = (TASK_CFG["staging_xy"][0], TASK_CFG["staging_xy"][1], TASK_CFG["pedestal_q"] - 0.05, TASK_CFG["pedestal_q"] + 0.05)
    cand = next(c for c in json.load(open(PROJECT_ROOT / "data/logs/stance_selection_timing_20261021_203414.json"))["layer2_candidates"] if abs(c["heading_deg"] + 90.0) < 1e-6)
    B = (cand["x"], cand["y"], cand["q_lo"], cand["q_hi"])
    out["stances"] = {"A (TASK_CFG)": A, "B (first layer 2 candidate at -90 degrees)": B}
    ins = Instr()
    for label, st, runs in (("A cold", A, 1), ("A warm", A, 1)):
        instrument(ins, chk, R)
        STAT.clear()
        res = layer3(chk, R, *st, heading, qs)
        res["counters"] = snapshot()
        ins.off()
        out[label] = res
        print(f"{label}: {res['heights']} heights, {res['passing_heights']} pass; requirements {res['requirements_seconds']} s, IK {res['ik_seconds']} s, total {res['total_seconds']} s", flush=True)
    # cProfile run, wrappers off
    prof = cProfile.Profile()
    prof.enable()
    resp = layer3(chk, R, *A, heading, qs)
    prof.disable()
    resp["note"] = "under cProfile: the times include the profiler's overhead"
    out["A profiled"] = resp
    stamp = time.strftime("%Y%m%d_%H%M%S")
    prof.dump_stats(str(Path(args.out) / f"stance_check_profile_{stamp}.prof"))
    sio = io.StringIO()
    st = pstats.Stats(prof, stream=sio).sort_stats("cumulative")
    st.print_stats(40)
    out["cprofile_top40_cumulative"] = sio.getvalue()
    print(f"A profiled: total {resp['total_seconds']} s (with the profiler)", flush=True)
    instrument(ins, chk, R)
    STAT.clear()
    resb = layer3(chk, R, *B, heading, qs)
    resb["counters"] = snapshot()
    ins.off()
    out["B"] = resb
    print(f"B: {resb['heights']} heights, {resb['passing_heights']} pass, failed: {resb['failed_at']}; total {resb['total_seconds']} s", flush=True)
    p = Path(args.out) / f"stance_check_profile_{stamp}.json"
    p.write_text(json.dumps(out, indent=1, default=str))
    print(f"written {p}")


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--out", default=str(PROJECT_ROOT / "data" / "logs"))
    main(ap.parse_args())
